module div_16bit(
    input [15:0] A, 
    input [7:0] B,
    output reg [15:0] result, 
    output reg [15:0] odd
);
// Combinational logic for division
always @(*) begin
    if (B == 0) begin
        result = 0;
        odd = A;
    end else begin
        result = A / B;
        odd = A % B;
    end
end
endmodule
